const SYSTEM_PROMPTS: Record<string, string> = {
  title: "",
  summary: "你是苏州律师吕婷，江苏臻万律师事务所副主任。根据文章内容写一段100-150字的摘要，用你自己的语气。摘要末尾另起一行，输出此行+此领域相关的5-10个SEO热门搜索关键词，每个以#开头，用空格分隔。直接返回摘要文本及关键词。",
  article: "",
};

export async function POST(req: NextRequest) {
  try {
    const { type = "article", style = "原创写作", theme = "经典", topic, content, model, systemPrompt: customSystemPrompt } = await req.json();
    const cfg = getModelConfig(model as string | undefined);

    if (!cfg) {
      return NextResponse.json({ error: "请在左侧 AI 设置中配置大模型和密钥" }, { status: 500 });
    }
    if (type !== "title" && !topic && !content) {
      return NextResponse.json({ error: "请输入主题或内容" }, { status: 400 });
    }

    let systemPrompt = "";

    if (type === "article") {
      if (customSystemPrompt) {
        systemPrompt = customSystemPrompt;
      } else {
        const stylePrompt = STYLE_PROMPTS[style] || STYLE_PROMPTS["原创写作"];
        const themePrompt = THEME_PROMPTS[theme] || THEME_PROMPTS["经典"];
        systemPrompt = stylePrompt + themePrompt + "文章开头必须先用h2标签写一句金句式标题——不概括全文，而是一句有冲击力的、读完正文回头再看会点头的话。只输出文章正文HTML片段，每个自然段必须用<p>标签包裹，禁止出现无标签的纯文本，不要输出<!DOCTYPE>、html、head、body标签，不要输出整页HTML。全文统一用'你'不用'您'。不要出现'根据您提供的材料''作为专业文章''我将为您解析'等自我叙述。";
      }
    } else if (type === "title") {
      if (customSystemPrompt) {
        systemPrompt = customSystemPrompt + "\n\n## 执行规则\n输出仅标题本身，无序号、无数字编号、无任何注释，每行一个标题";
      } else {
        systemPrompt = TITLE_BY_STYLE[style] || TITLE_BY_STYLE["原创写作"];
      }
    } else if (type === "summary") {
      systemPrompt = SYSTEM_PROMPTS.summary;
    }

    let userMessage = "";
    if (type === "article") {
      if (style === "改写" && content) userMessage = `请改写以下内容：\n\n${content}`;
      else if (style === "仿写" && content) userMessage = `请参考以下文章，写一篇关于"${topic}"的新文章：\n\n参考文章：\n${content}`;
      else if (style === "案例评析" && content) userMessage = `请根据以下案例写案例评析：\n\n${content}`;
      else userMessage = content ? `请基于以下参考材料写一篇普法文章。事实部分严格准确，不要编造细节、金额、人名、地名、日期、判决结果。但不要只是复述案情——从素材细节中挖掘法律看点：盯住一个细节放大分析、把两个细节串起来揭示逻辑、追问背后的法律原则、从个案上升到实务经验。文章主体是你的分析和洞察（占一半以上篇幅），素材只是引子：\n\n${content}` : `主题：${topic}`;
    } else if (type === "summary") {
      userMessage = content ? `请为以下文章写摘要：\n\n${content}` : `主题：${topic}`;
    } else if (type === "title") {
      if (content) userMessage = `根据以下内容生成标题：\n\n${content}`;
      else if (topic) userMessage = `请参考以下关键词生成标题：${topic}`;
      else userMessage = "";
    }

    const res = await fetch(cfg.apiBase, {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: `Bearer ${cfg.apiKey}` },
      body: JSON.stringify({
        model: cfg.model,
        messages: [{ role: "system", content: systemPrompt }, { role: "user", content: userMessage }],
        temperature: 0.8,
        max_tokens: type === "article" ? 4096 : (type === "title" ? 2048 : 1024),
      }),
    });

    if (!res.ok) {
      const err = await res.text();
      console.error(`[${cfg.provider} API error]`, res.status, err);
      return NextResponse.json({ error: `AI 服务暂不可用 (${res.status})` }, { status: 502 });
    }

    const data = await res.json();
    const result = data.choices?.[0]?.message?.content || "";

    return NextResponse.json({ ok: true, result });
  } catch (err: any) {
    console.error("[/api/ai/generate]", err);
    return NextResponse.json({ error: "服务器错误" }, { status: 500 });
  }
}
